/**
 * Move attribute to display arbitrary text during a move's execution.
 */
export class MessageAttr extends MoveEffectAttr {
  /** The message to display, either as a string or a function returning one. */
  private readonly message: string | MoveMessageFunc;

  constructor(message: string | MoveMessageFunc, options?: MoveEffectAttrOptions) {
    // TODO: Do we need to respect `selfTarget` if we're just displaying text?
    super(false, options);
    this.message = message;
  }

  override apply(user: Pokemon, target: Pokemon, move: Move): boolean {
    const message = typeof this.message === "function" ? this.message(user, target, move) : this.message;

    // TODO: Consider changing if/when MoveAttr `apply` return values become significant
    if (message) {
      globalScene.phaseManager.queueMessage(message, 500);
      return true;
    }
    return false;
  }
}

export class RecoilAttr extends MoveEffectAttr {
  private readonly useHp: boolean;
  private readonly damageRatio: number;
  private readonly unblockable: boolean;

  constructor(useHp = false, damageRatio = 0.25, unblockable = false) {
    super(true, { lastHitOnly: true });

    this.useHp = useHp;
    this.damageRatio = damageRatio;
    this.unblockable = unblockable;
  }

  apply(user: Pokemon, target: Pokemon, move: Move, args: any[]): boolean {
    if (!super.apply(user, target, move, args)) {
      return false;
    }

    // don't do anything if a damaging recoil move didn't deal damage.
    // Whether this goes before or after the ability check is unobservable in mainline for lack of a flyout,
    // but putting it first avoids giving information to the enemy trainer AI that's ambiguous.
    if (!this.useHp && user.turnData.totalDamageDealt === 0) {
      return false;
    }

    const cancelled = new BooleanHolder(false);
    if (!this.unblockable) {
      const abAttrParams: AbAttrParamsWithCancel = { pokemon: user, cancelled };
      applyAbAttrs("BlockRecoilDamageAttr", abAttrParams);
      applyAbAttrs("BlockNonDirectDamageAbAttr", abAttrParams);
    }

    if (cancelled.value) {
      return false;
    }

    // Chloroblast and Struggle should not deal recoil damage if the move was not successful
    if (
      this.useHp
      && [MoveResult.FAIL, MoveResult.MISS].includes(user.getLastXMoves(1)[0]?.result ?? MoveResult.FAIL)
    ) {
      return false;
    }

    const recoilDamage = toDmgValue((this.useHp ? user.getMaxHp() : user.turnData.totalDamageDealt) * this.damageRatio);

    user.damageAndUpdate(recoilDamage, { result: HitResult.INDIRECT, ignoreSegments: true });
    globalScene.phaseManager.queueMessage(
      i18next.t("moveTriggers:hitWithRecoil", { pokemonName: getPokemonNameWithAffix(user) }),
    );
    user.turnData.damageTaken += recoilDamage;

    return true;
  }

  getUserBenefitScore(_user: Pokemon, _target: Pokemon, move: Move): number {
    return Math.floor(move.power / 5 / -4);
  }
}

/**
 * Attribute used for moves which self KO the user regardless if the move hits a target
 */
export class SacrificialAttr extends MoveEffectAttr {
  constructor() {
    super(true, { trigger: MoveEffectTrigger.POST_TARGET });
  }

  /**
   * Deals damage to the user equal to their current hp
   * @param user {@linkcode Pokemon} that used the move
   * @param target {@linkcode Pokemon} target of the move
   * @param move {@linkcode Move} with this attribute
   * @param args N/A
   * @returns true if the function succeeds
   */
  apply(user: Pokemon, _target: Pokemon, _move: Move, _args: any[]): boolean {
    user.damageAndUpdate(user.hp, { result: HitResult.INDIRECT, ignoreSegments: true });
    user.turnData.damageTaken += user.hp;

    return true;
  }

  getUserBenefitScore(user: Pokemon, target: Pokemon, move: Move): number {
    if (user.isBoss()) {
      return -20;
    }
    return Math.ceil(
      ((1 - user.getHpRatio()) * 10 - 10) * (target.getAttackTypeEffectiveness(move.type, { source: user }) - 0.5),
    );
  }
}

/**
 * Attribute used for moves which self KO the user but only if the move hits a target
 */
export class SacrificialAttrOnHit extends MoveEffectAttr {
  constructor() {
    super(true);
  }

  /**
   * Deals damage to the user equal to their current hp if the move lands
   * @param user {@linkcode Pokemon} that used the move
   * @param target {@linkcode Pokemon} target of the move
   * @param move {@linkcode Move} with this attribute
   * @param args N/A
   * @returns true if the function succeeds
   */
  apply(user: Pokemon, target: Pokemon, move: Move, args: any[]): boolean {
    // If the move fails to hit a target, then the user does not faint and the function returns false
    if (!super.apply(user, target, move, args)) {
      return false;
    }

    user.damageAndUpdate(user.hp, { result: HitResult.INDIRECT, ignoreSegments: true });
    user.turnData.damageTaken += user.hp;

    return true;
  }

  getUserBenefitScore(user: Pokemon, target: Pokemon, move: Move): number {
    if (user.isBoss()) {
      return -20;
    }
    return Math.ceil(
      ((1 - user.getHpRatio()) * 10 - 10) * (target.getAttackTypeEffectiveness(move.type, { source: user }) - 0.5),
    );
  }
}

/**
 * Attribute used for moves which cut the user's Max HP in half.
 * Triggers using {@linkcode MoveEffectTrigger.POST_TARGET}.
 */
export class HalfSacrificialAttr extends MoveEffectAttr {
  constructor() {
    super(true, { trigger: MoveEffectTrigger.POST_TARGET });
  }

  /**
   * Cut's the user's Max HP in half and displays the appropriate recoil message
   * @param user {@linkcode Pokemon} that used the move
   * @param target N/A
   * @param move {@linkcode Move} with this attribute
   * @param args N/A
   * @returns true if the function succeeds
   */
  apply(user: Pokemon, target: Pokemon, move: Move, args: any[]): boolean {
    if (!super.apply(user, target, move, args)) {
      return false;
    }

    const cancelled = new BooleanHolder(false);
    // Check to see if the Pokemon has an ability that blocks non-direct damage
    applyAbAttrs("BlockNonDirectDamageAbAttr", { pokemon: user, cancelled });
    if (!cancelled.value) {
      user.damageAndUpdate(toDmgValue(user.getMaxHp() / 2), { result: HitResult.INDIRECT, ignoreSegments: true });
      globalScene.phaseManager.queueMessage(
        i18next.t("moveTriggers:cutHpPowerUpMove", { pokemonName: getPokemonNameWithAffix(user) }),
      ); // Queue recoil message
    }
    return true;
  }

  getUserBenefitScore(user: Pokemon, target: Pokemon, move: Move): number {
    if (user.isBoss()) {
      return -10;
    }
    return Math.ceil(
      ((1 - user.getHpRatio() / 2) * 10 - 10) * (target.getAttackTypeEffectiveness(move.type, { source: user }) - 0.5),
    );
  }
}

/**
 * Attribute to put in a {@link https://bulbapedia.bulbagarden.net/wiki/Substitute_(doll) | Substitute Doll} for the user.
 *
 * Used for {@linkcode MoveId.SUBSTITUTE} and {@linkcode MoveId.SHED_TAIL}.
 */
export class AddSubstituteAttr extends MoveEffectAttr {
  /** The percentage of the user's maximum HP that is required to apply this effect. */
  private readonly hpCost: number;
  /** Whether the damage taken should be rounded up (Shed Tail rounds up). */
  private readonly roundUp: boolean;

  constructor(hpCost: number, roundUp: boolean) {
    super(true);

    this.hpCost = hpCost;
    this.roundUp = roundUp;
  }

  /**
   * Helper function to compute the amount of HP required to create a substitute.
   * @param user - The {@linkcode Pokemon} using the move
   * @returns The amount of HP that is required to create a substitute.
   */
  private getHpCost(user: Pokemon): number {
    return (this.roundUp ? Math.ceil : toDmgValue)(user.getMaxHp() * this.hpCost);
  }

  /**
   * Remove a fraction of the user's maximum HP to create a 25% HP substitute doll.
   * @param user - The {@linkcode Pokemon} using the move
   * @param target - n/a
   * @param move - The {@linkcode Move} being used
   * @param args - n/a
   * @returns Whether the attribute successfully applied
   */
  public override apply(user: Pokemon, target: Pokemon, move: Move, args: any[]): boolean {
    if (!super.apply(user, target, move, args)) {
      return false;
    }

    const dmgTaken = this.getHpCost(user);
    user.damageAndUpdate(dmgTaken, { result: HitResult.INDIRECT, ignoreSegments: true, ignoreFaintPhase: true });
    user.addTag(BattlerTagType.SUBSTITUTE, 0, move.id, user.id);
    return true;
  }

  public override getUserBenefitScore(user: Pokemon, _target: Pokemon, _move: Move): number {
    if (user.isBoss()) {
      return -10;
    }
    return 5;
  }

  public override getCondition(): MoveConditionFunc {
    return user => !user.getTag(SubstituteTag) && user.hp > this.getHpCost(user);
  }

  public override getFailedText(user: Pokemon): string | undefined {
    if (user.getTag(SubstituteTag)) {
      return i18next.t("moveTriggers:substituteOnOverlap", { pokemonName: getPokemonNameWithAffix(user) });
    }
    if (user.hp <= this.getHpCost(user)) {
      return i18next.t("moveTriggers:substituteNotEnoughHp");
    }
  }
}

/**
 * Attribute to implement healing moves, such as Recover or Softboiled.
 *
 * Heals the user or target of the move by a fixed amount relative to their maximum HP.
 */
export class HealAttr extends MoveEffectAttr {
  /** The percentage of HP to heal, relative to the user/target's maximum. */
  protected healRatio: number;
  /**
   * Whether to display a healing animation upon healing the target.
   * @defaultValue `false`
   */
  private readonly showAnim: boolean;
  /**
   * Whether the move should count as failed if the target is at full HP.
   * @defaultValue `true`
   */
  // TODO: Remove post move failure rework -
  // this solely exists to prevent Lunar Blessing and co. from failing
  private readonly failOnFullHp: boolean;

  constructor(healRatio: number, showAnim = false, selfTarget = true, failOnFullHp = true) {
    super(selfTarget);

    this.healRatio = healRatio;
    this.showAnim = showAnim;
    this.failOnFullHp = failOnFullHp;
  }

  override apply(user: Pokemon, target: Pokemon, move: Move, args: any[]): boolean {
    if (!super.apply(user, target, move, args)) {
      return false;
    }

    const healRatio = new ValueHolder(this.healRatio);
    applyAbAttrs("MoveHealBoostAbAttr", { pokemon: user, opponent: target, move, healRatio });
    this.addHealPhase(this.selfTarget ? user : target, healRatio.value);
    return true;
  }

  /**
   * Helper function to create a new {@linkcode PokemonHealPhase}.
   * @param healedPokemon - The {@linkcode Pokemon} being healed
   * @param healRatio - The percentage of HP to heal
   */
  protected addHealPhase(healedPokemon: Pokemon, healRatio: number): void {
    globalScene.phaseManager.unshiftNew(
      "PokemonHealPhase",
      healedPokemon.getBattlerIndex(),
      // NB: Healing moves always round their base amounts half up
      // (unlike most other sources of damage which round down).
      Math.round(healedPokemon.getMaxHp() * healRatio),
      {
        message: i18next.t("moveTriggers:healHp", { pokemonName: getPokemonNameWithAffix(healedPokemon) }),
        showFullHpMessage: true,
        skipAnim: !this.showAnim,
      },
    );
  }

  override getTargetBenefitScore(user: Pokemon, target: Pokemon, _move: Move): number {
    const score = (1 - (this.selfTarget ? user : target).getHpRatio()) * 20 - this.healRatio * 10;
    return Math.round(score / (1 - this.healRatio / 2));
  }

  public override getCondition(): MoveConditionFunc {
    return (user, target) => !(this.failOnFullHp && (this.selfTarget ? user : target).isFullHp());
  }

  public override getFailedText(user: Pokemon, target: Pokemon): string | undefined {
    const healedPokemon = this.selfTarget ? user : target;
    if (healedPokemon.isFullHp()) {
      return i18next.t("battle:hpIsFull", { pokemonName: getPokemonNameWithAffix(healedPokemon) });
    }
  }
}

/**
 * Attribute to put the user to sleep for a fixed duration, fully heal them and cure their status.
 * Used by Rest.
 */
// TODO: Move the status-based stuff to `addHealPhase` and remove `overrideStatus` parameters from status-related functions
export class RestAttr extends HealAttr {
  private readonly duration: number;

  constructor(duration: number) {
    super(1, true);
    this.duration = duration;
  }

  public override apply(user: Pokemon, target: Pokemon, move: Move, args: any[]): boolean {
    // TODO: Revisit/review having Rest show its message on gaining its status vs being healed -
    // I am not sure if it is correct (and results in somewhat more complex code)
    const wasSet = user.trySetStatus(
      StatusEffect.SLEEP,
      user,
      this.duration,
      null,
      true,
      true,
      i18next.t("moveTriggers:restBecameHealthy", {
        pokemonName: getPokemonNameWithAffix(user),
      }),
    );
    return wasSet && super.apply(user, target, move, args);
  }

  protected override addHealPhase(user: Pokemon): void {
    globalScene.phaseManager.unshiftNew("PokemonHealPhase", user.getBattlerIndex(), user.getMaxHp());
  }

  public override getCondition(): MoveConditionFunc {
    return (user, target, move) =>
      super.getCondition()(user, target, move) // Intentionally suppress messages here as we display generic fail msg // TODO: This might have order-of-operation jank
      && user.canSetStatus(StatusEffect.SLEEP, true, true, user);
  }
}

/**
 * Attribute for moves with variable healing amounts.
 *
 * Heals the user/target by an amount depending on the return value of {@linkcode healFunc}.
 *
 * Used for moves such as Moonlight and variants.
 */
export class VariableHealAttr extends HealAttr {
  /** A lambda function yielding the amount of HP to heal. */
  private readonly healFunc: (user: Pokemon) => number;

  constructor(healFunc: (user: Pokemon) => number, showAnim = false, selfTarget = true, failOnFullHp = true) {
    super(1, showAnim, selfTarget, failOnFullHp);

    this.healFunc = healFunc;
  }

  apply(user: Pokemon, target: Pokemon, move: Move, args: any[]): boolean {
    this.healRatio = this.healFunc(user);
    return super.apply(user, target, move, args);
  }
}

/**
 * Heals the target only if it is an ally.
 * Used for Pollen Puff.
 */
export class HealOnAllyAttr extends HealAttr {
  public override canApply(user: Pokemon, target: Pokemon, move: Move, args: any[]): boolean {
    return target === user.getAlly() && super.canApply(user, target, move, args);
  }

  public override apply(user: Pokemon, target: Pokemon, move: Move, args: any[]): boolean {
    if (user.isOpponent(target)) {
      return false;
    }
    return super.apply(user, target, move, args);
  }

  public override getCondition(): MoveConditionFunc {
    return (user, target, _move) => user.isOpponent(target) || super.getCondition()(user, target, _move);
  }
}

/**
 * Cures the user's party of non-volatile status conditions, ie. Heal Bell, Aromatherapy
 */
export class PartyStatusCureAttr extends MoveEffectAttr {
  /** Message to display after using move */
  private readonly message: string | null;
  /** Skips mons with this ability, ie. Soundproof */
  private readonly abilityCondition: AbilityId;

  constructor(message: string | null, abilityCondition: AbilityId) {
    super();

    this.message = message;
    this.abilityCondition = abilityCondition;
  }

  //The same as MoveEffectAttr.canApply, except it doesn't check for the target's HP.
  canApply(user: Pokemon, target: Pokemon, move: Move, _args: any[]) {
    const isTargetValid =
      (this.selfTarget && user.hp && !user.getTag(BattlerTagType.FRENZY))
      || (!this.selfTarget && (!target.getTag(BattlerTagType.PROTECTED) || move.hasFlag(MoveFlags.IGNORE_PROTECT)));
    return !!isTargetValid;
  }

  apply(user: Pokemon, target: Pokemon, move: Move, args: any[]): boolean {
    if (!this.canApply(user, target, move, args)) {
      return false;
    }
    const partyPokemon = user.isPlayer() ? globalScene.getPlayerParty() : globalScene.getEnemyParty();
    for (const p of partyPokemon) {
      this.cureStatus(p, user.id);
    }

    if (this.message) {
      globalScene.phaseManager.queueMessage(this.message);
    }

    return true;
  }

  /**
   * Tries to cure the status of the given {@linkcode Pokemon}
   * @param pokemon The {@linkcode Pokemon} to cure.
   * @param userId The ID of the (move) {@linkcode Pokemon | user}.
   */
  public cureStatus(pokemon: Pokemon, userId: number) {
    if (!pokemon.isOnField() || pokemon.id === userId) {
      // user always cures its own status, regardless of ability
      pokemon.resetStatus(false);
      pokemon.updateInfo();
    } else if (pokemon.hasAbility(this.abilityCondition)) {
      // TODO: Ability displays should be handled by the ability
      globalScene.phaseManager.queueAbilityDisplay(
        pokemon,
        pokemon.getPassiveAbility()?.id === this.abilityCondition,
        true,
      );
      globalScene.phaseManager.queueAbilityDisplay(
        pokemon,
        pokemon.getPassiveAbility()?.id === this.abilityCondition,
        false,
      );
    } else {
      pokemon.resetStatus();
      pokemon.updateInfo();
    }
  }
}

/**
 * Applies damage to the target's ally equal to 1/16 of that ally's max HP.
 */
export class FlameBurstAttr extends MoveEffectAttr {
  constructor() {
    /**
     * This is self-targeted to bypass immunity to target-facing secondary
     * effects when the target has an active Substitute doll.
     * TODO: Find a more intuitive way to implement Substitute bypassing.
     */
    super(true);
  }
  /**
   * @param user - n/a
   * @param target - The target Pokémon.
   * @param move - n/a
   * @param args - n/a
   * @returns A boolean indicating whether the effect was successfully applied.
   */
  apply(_user: Pokemon, target: Pokemon, _move: Move, _args: any[]): boolean {
    const targetAlly = target.getAlly();
    const cancelled = new BooleanHolder(false);

    if (targetAlly != null) {
      applyAbAttrs("BlockNonDirectDamageAbAttr", { pokemon: targetAlly, cancelled });
    }

    if (cancelled.value || !targetAlly || targetAlly.switchOutStatus) {
      return false;
    }

    targetAlly.damageAndUpdate(Math.max(1, Math.floor((1 / 16) * targetAlly.getMaxHp())), {
      result: HitResult.INDIRECT,
    });
    return true;
  }

  getTargetBenefitScore(_user: Pokemon, target: Pokemon, _move: Move): number {
    return target.getAlly() == null ? 0 : -5;
  }
}

export class SacrificialFullRestoreAttr extends SacrificialAttr {
  protected restorePP: boolean;
  protected moveMessage: string;

  constructor(restorePP: boolean, moveMessage: string) {
    super();

    this.restorePP = restorePP;
    this.moveMessage = moveMessage;
  }

  apply(user: Pokemon, target: Pokemon, move: Move, args: any[]): boolean {
    if (!super.apply(user, target, move, args)) {
      return false;
    }

    // Add a tag to the field if it doesn't already exist, then queue a delayed healing effect in the user's current slot.
    globalScene.arena.addTag(ArenaTagType.PENDING_HEAL, 0, move.id, user.id); // Arguments after first go completely unused
    const tag = globalScene.arena.getTag(ArenaTagType.PENDING_HEAL) as PendingHealTag;
    tag.queueHeal(user.getBattlerIndex(), {
      sourceId: user.id,
      moveId: move.id,
      restorePP: this.restorePP,
      healMessage: i18next.t(this.moveMessage, { pokemonName: getPokemonNameWithAffix(user) }),
    });

    return true;
  }

  getUserBenefitScore(_user: Pokemon, _target: Pokemon, _move: Move): number {
    return -20;
  }

  getCondition(): MoveConditionFunc {
    return (_user, _target, _move) =>
      globalScene.getPlayerParty().filter(p => p.isActive()).length > globalScene.currentBattle.getBattlerCount();
  }
}

/**
 * Attribute used for moves that that get the weather boost without being the
 * corresponding weather type
 * @see {@link https://bulbapedia.bulbagarden.net/wiki/Hydro_Steam_(move)}
 */
export class OverrideWeatherMultiplierAttr extends MoveAttr {
  /** The {@linkcode WeatherType} this move overrides the multiplier of */
  public readonly weather: WeatherType;

  constructor(weather: WeatherType) {
    super();

    this.weather = weather;
  }

  /**
   * Note: This shouldn't be invoked; use `getWeatherMultiplierForMove` which
   * handles the logic for adjusting the multiplier.
   * @param _user
   * @param _target
   * @param _move
   * @param param3
   * @returns
   */
  apply(
    _user: Pokemon,
    _target: Pokemon,
    _move: Move,
    [weatherMultiplier, weatherType]: [weatherMultiplier: ValueHolder<number>, weatherType: WeatherType],
  ): boolean {
    if (weatherType === this.weather) {
      weatherMultiplier.value = 1.5;
      return true;
    }
    return false;
  }
}

/**
 * Heals user as a side effect of a move that hits a target.
 * Healing is based on {@linkcode healRatio} * the amount of damage dealt or a stat of the target.
 */
// TODO: Make Strength Sap its own attribute that extends off of this one
export class HitHealAttr extends MoveEffectAttr {
  private readonly healRatio: number;
  private readonly healStat: EffectiveStat | null;

  constructor(healRatio?: number | null, healStat?: EffectiveStat) {
    super(true);

    this.healRatio = healRatio ?? 0.5;
    this.healStat = healStat ?? null;
  }
  /**
   * Heals the user the determined amount and possibly displays a message about regaining health.
   * If the target has the {@linkcode ReverseDrainAbAttr}, all healing is instead converted
   * to damage to the user.
   * @param user {@linkcode Pokemon} using this move
   * @param target {@linkcode Pokemon} target of this move
   * @param move {@linkcode Move} being used
   * @param args N/A
   * @returns true if the function succeeds
   */
  apply(user: Pokemon, target: Pokemon, _move: Move, _args: any[]): boolean {
    if (target.hasAbilityWithAttr("ReverseDrainAbAttr")) {
      return false;
    }

    const healAmount = this.getHealAmount(user, target);
    let message: string;
    if (this.healStat === null) {
      message = i18next.t("battle:regainHealth", { pokemonName: getPokemonNameWithAffix(user) });
    } else {
      message = i18next.t("battle:drainMessage", { pokemonName: getPokemonNameWithAffix(target) });
    }

    globalScene.phaseManager.unshiftNew(
      "PokemonHealPhase", //
      user.getBattlerIndex(),
      healAmount,
      { message, showFullHpMessage: false, skipAnim: true },
    );
    return true;
  }

  /**
   * Used by the Enemy AI to rank an attack based on a given user
   * @param user {@linkcode Pokemon} using this move
   * @param target {@linkcode Pokemon} target of this move
   * @param move {@linkcode Move} being used
   * @returns an integer. Higher means enemy is more likely to use that move.
   */
  getUserBenefitScore(user: Pokemon, target: Pokemon, move: Move): number {
    if (this.healStat) {
      const healAmount = target.getEffectiveStat(this.healStat);
      return Math.floor(Math.max(0, Math.min(1, (healAmount + user.hp) / user.getMaxHp() - 0.33)) / user.getHpRatio());
    }
    return Math.floor(Math.max(1 - user.getHpRatio() - 0.33, 0) * (move.power / 4));
  }

  public getHealAmount(user: Pokemon, target: Pokemon): number {
    return this.healStat
      ? target.getEffectiveStat(this.healStat)
      : toDmgValue(user.turnData.singleHitDamageDealt * this.healRatio);
  }
}

/**
 * Attribute used for moves that change priority in a turn given a condition,
 * e.g. Grassy Glide
 * Called when move order is calculated in {@linkcode TurnStartPhase}.
 */
export class IncrementMovePriorityAttr extends MoveAttr {
  /** The condition for a move's priority being incremented */
  private readonly moveIncrementFunc: (pokemon: Pokemon, target: Pokemon, move: Move) => boolean;
  /** The amount to increment priority by, if condition passes. */
  private readonly increaseAmount: number;

  constructor(moveIncrementFunc: (pokemon: Pokemon, target: Pokemon, move: Move) => boolean, increaseAmount = 1) {
    super();

    this.moveIncrementFunc = moveIncrementFunc;
    this.increaseAmount = increaseAmount;
  }

  /**
   * Increments move priority by set amount if condition passes
   * @param user {@linkcode Pokemon} using this move
   * @param target {@linkcode Pokemon} target of this move
   * @param move {@linkcode Move} being used
   * @param args [0] {@linkcode NumberHolder} for move priority.
   * @returns true if function succeeds
   */
  apply(user: Pokemon, target: Pokemon, move: Move, args: any[]): boolean {
    if (!this.moveIncrementFunc(user, target, move)) {
      return false;
    }

    (args[0] as NumberHolder).value += this.increaseAmount;
    return true;
  }
}

/**
 * Attribute used for attack moves that hit multiple times per use, e.g. Bullet Seed.
 *
 * @remarks
 * Applied at the beginning of {@linkcode MoveEffectPhase}.
 */
export class MultiHitAttr extends MoveAttr {
  /** This move's intrinsic multi-hit type. It should never be modified. */
  private readonly intrinsicMultiHitType: MultiHitType;
  /** This move's current multi-hit type. It may be temporarily modified by abilities (e.g., Battle Bond). */
  private multiHitType: MultiHitType;

  constructor(multiHitType?: MultiHitType) {
    super();

    this.intrinsicMultiHitType = multiHitType === undefined ? MultiHitType.TWO_TO_FIVE : multiHitType;
    this.multiHitType = this.intrinsicMultiHitType;
  }

  // Currently used by `battle_bond.test.ts`
  getMultiHitType(): MultiHitType {
    return this.multiHitType;
  }

  /**
   * Set the hit count of an attack based on this attribute instance's {@linkcode MultiHitType}.
   * If the target has an immunity to this attack's types, the hit count will always be 1.
   *
   * @param user {@linkcode Pokemon} that used the attack
   * @param target {@linkcode Pokemon} targeted by the attack
   * @param move {@linkcode Move} being used
   * @param args [0] {@linkcode NumberHolder} storing the hit count of the attack
   * @returns True
   */
  apply(user: Pokemon, target: Pokemon, move: Move, args: any[]): boolean {
    const hitType = new NumberHolder(this.intrinsicMultiHitType);
    applyMoveAttrs("ChangeMultiHitTypeAttr", user, target, move, hitType);
    this.multiHitType = hitType.value;

    (args[0] as NumberHolder).value = this.getHitCount(user, target);
    return true;
  }

  getTargetBenefitScore(_user: Pokemon, _target: Pokemon, _move: Move): number {
    return -5;
  }

  /**
   * Calculate the number of hits that an attack should have given this attribute's
   * {@linkcode MultiHitType}.
   *
   * @param user {@linkcode Pokemon} using the attack
   * @param target {@linkcode Pokemon} targeted by the attack
   * @returns The number of hits this attack should deal
   */
  getHitCount(user: Pokemon, _target: Pokemon): number {
    switch (this.multiHitType) {
      case MultiHitType.TWO_TO_FIVE: {
        const rand = user.randBattleSeedInt(20);
        const hitValue = new NumberHolder(rand);
        applyAbAttrs("MaxMultiHitAbAttr", { pokemon: user, hits: hitValue });
        if (hitValue.value >= 13) {
          return 2;
        }
        if (hitValue.value >= 6) {
          return 3;
        }
        if (hitValue.value >= 3) {
          return 4;
        }
        return 5;
      }
      case MultiHitType.TWO:
        return 2;
      case MultiHitType.THREE:
        return 3;
      case MultiHitType.TEN:
        return 10;
      case MultiHitType.BEAT_UP: {
        const party = user.isPlayer() ? globalScene.getPlayerParty() : globalScene.getEnemyParty();
        // No status means the ally pokemon can contribute to Beat Up
        return party.reduce((total, pokemon) => {
          return (
            total
            + (pokemon.id === user.id ? 1 : pokemon?.status && pokemon.status.effect !== StatusEffect.NONE ? 0 : 1)
          );
        }, 0);
      }
    }
  }

  /**
   * Calculate the expected number of hits given this attribute's {@linkcode MultiHitType},
   * the move's accuracy, and a number of situational parameters.
   *
   * @param move - The move that this attribtue is applied to
   * @param partySize - The size of the user's party, used for {@linkcode MoveId.BEAT_UP | Beat Up} (default: `1`)
   * @param maxMultiHit - Whether the move should always hit the maximum number of times, e.g. due to {@linkcode AbilityId.SKILL_LINK | Skill Link} (default: `false`)
   * @param ignoreAcc - `true` if the move should ignore accuracy checks, e.g. due to  {@linkcode AbilityId.NO_GUARD | No Guard} (default: `false`)
   */
  calculateExpectedHitCount(
    move: Move,
    {
      ignoreAcc = false,
      maxMultiHit = false,
      partySize = 1,
      accMultiplier = 1,
    }: { ignoreAcc?: boolean; maxMultiHit?: boolean | undefined; partySize?: number; accMultiplier?: number } = {},
  ): number {
    let expectedHits: number;
    switch (this.multiHitType) {
      case MultiHitType.TWO_TO_FIVE:
        expectedHits = maxMultiHit ? 5 : 3.1;
        break;
      case MultiHitType.TWO:
        expectedHits = 2;
        break;
      case MultiHitType.THREE:
        expectedHits = 3;
        break;
      case MultiHitType.TEN:
        expectedHits = 10;
        break;
      case MultiHitType.BEAT_UP:
        // Estimate that half of the party can contribute to beat up.
        expectedHits = Math.max(1, partySize / 2);
        break;
    }
    if (ignoreAcc || move.accuracy === -1) {
      return expectedHits;
    }
    const acc = Math.min((move.accuracy / 100) * accMultiplier, 100);
    if (move.hasFlag(MoveFlags.CHECK_ALL_HITS) && !maxMultiHit) {
      // N.B. No moves should be the _2_TO_5 variant and have the CHECK_ALL_HITS flag.
      return (acc * (1 - Math.pow(acc, expectedHits))) / (1 - acc);
    }
    return (expectedHits *= acc);
  }
}

