/**
 * Move effect to force the target to move last, ignoring priority.
 * If applied to multiple targets, they move in speed order after all other moves.
 */
export class ForceLastAttr extends MoveEffectAttr {
  /**
   * Forces the target of this move to move last.
   *
   * @param user {@linkcode Pokemon} that is using the move.
   * @param target {@linkcode Pokemon} that will be forced to move last.
   * @param move {@linkcode Move} {@linkcode MoveId.QUASH}
   * @param _args N/A
   * @returns true
   */
  override apply(_user: Pokemon, target: Pokemon, _move: Move, _args: any[]): boolean {
    globalScene.phaseManager.queueMessage(
      i18next.t("moveTriggers:forceLast", { targetPokemonName: getPokemonNameWithAffix(target) }),
    );

    globalScene.phaseManager.forceMoveLast((phase: MovePhase) => phase.pokemon === target);
    return true;
  }
}

// #region Condition functions

const failOnGroundedCondition: MoveConditionFunc = (_user, target) => !target.getTag(BattlerTagType.IGNORE_FLYING);

const failOnBossCondition: MoveConditionFunc = (_user, target) => !target.isBossImmune();

const failIfSingleBattle: MoveConditionFunc = () => globalScene.currentBattle.double;

const failIfLastCondition: MoveConditionFunc = () => globalScene.phaseManager.hasPhaseOfType("MovePhase");

const failIfLastInPartyCondition: MoveConditionFunc = user => {
  const party: Pokemon[] = user.isPlayer() ? globalScene.getPlayerParty() : globalScene.getEnemyParty();
  return party.some(pokemon => pokemon.isActive() && !pokemon.isOnField());
};

const failIfGhostTypeCondition: MoveConditionFunc = (_user, target) => !target.isOfType(PokemonType.GHOST);

const failIfNoTargetHeldItemsCondition: MoveConditionFunc = (_user, target) =>
  target.getHeldItems().filter(i => i.isTransferable)?.length > 0;

// #endregion Condition functions

const attackedByItemMessageFunc: MoveMessageFunc = (_user, target) => {
  if (target == null) {
    // Fix bug when used against targets that have both fainted
    return "";
  }
  const heldItems = target.getHeldItems().filter(i => i.isTransferable);
  if (heldItems.length === 0) {
    return "";
  }
  const itemName = heldItems[0]?.type?.name ?? "item";
  const message: string = i18next.t("moveTriggers:attackedByItem", {
    pokemonName: getPokemonNameWithAffix(target),
    itemName,
  });
  return message;
};

const sunnyHealRatioFunc = (user: Pokemon): number => {
  const weatherType = getEffectiveWeatherForMove(user);
  switch (weatherType) {
    case WeatherType.SUNNY:
    case WeatherType.HARSH_SUN:
      return 2 / 3;
    case WeatherType.RAIN:
    case WeatherType.SANDSTORM:
    case WeatherType.HAIL:
    case WeatherType.SNOW:
    case WeatherType.HEAVY_RAIN:
    case WeatherType.FOG:
      return 1 / 4;
    case WeatherType.STRONG_WINDS:
    case WeatherType.NONE:
      return 1 / 2;
  }
};

const shoreUpHealRatioFunc = (user: Pokemon): number => {
  return getEffectiveWeatherForMove(user) === WeatherType.SANDSTORM ? 2 / 3 : 1 / 2;
};

const swallowHealFunc = (user: Pokemon): number => {
  const tag = user.getTag(BattlerTagType.STOCKPILING);
  if (!tag || tag.stockpiledCount <= 0) {
    return 0;
  }

  switch (tag.stockpiledCount) {
    case 1:
      return 0.25;
    case 2:
      return 0.5;
    case 3:
    default: // in case we ever get more stacks
      return 1;
  }
};

/**
 * Attribute used for Conversion 2, to convert the user's type to a random type that resists the target's last used move.
 */
// TODO: If a move has its type changed (e.g. Hidden Power), it should check the new type.
// TODO: Does not fail when it should
export class ResistLastMoveTypeAttr extends MoveEffectAttr {
  constructor() {
    super(true);
  }

  /**
   * User changes its type to a random type that resists the target's last used move
   * @param user Pokemon that used the move and will change types
   * @param target Opposing pokemon that recently used a move
   * @param move Move being used
   * @param args Unused
   * @returns true if the function succeeds
   */
  apply(user: Pokemon, target: Pokemon, move: Move, args: any[]): boolean {
    if (!super.apply(user, target, move, args)) {
      return false;
    }

    // TODO: Confirm how this interacts with status-induced failures and called moves
    const targetMove = target.getLastXMoves(1)[0]; // target's most recent move
    if (!targetMove) {
      return false;
    }

    const moveData = allMoves[targetMove.move];
    if (moveData.type === PokemonType.STELLAR || moveData.type === PokemonType.UNKNOWN) {
      return false;
    }
    const validTypes = this.getTypeResistances(user, moveData.type);
    if (validTypes.length === 0) {
      return false;
    }
    const type = validTypes[user.randBattleSeedInt(validTypes.length)];
    user.summonData.types = [type];
    globalScene.phaseManager.queueMessage(
      i18next.t("battle:transformedIntoType", {
        pokemonName: getPokemonNameWithAffix(user),
        type: toTitleCase(PokemonType[type]),
      }),
    );
    user.updateInfo();

    return true;
  }

  /**
   * Retrieve the types resisting a given type. Used by Conversion 2
   * @param moveType - The type of the move having been used
   * @returns An array containing all types that resist the given move's type
   * and are not currently shared by the user
   */
  private getTypeResistances(user: Pokemon, moveType: PokemonType): PokemonType[] {
    const resistances: PokemonType[] = [];
    const userTypes = user.getTypes({ returnOriginalTypesIfStellar: true });

    for (const type of getEnumValues(PokemonType)) {
      if (userTypes.includes(type)) {
        continue;
      }
      const multiplier = getTypeDamageMultiplier(moveType, type);
      if (multiplier < 1) {
        resistances.push(type);
      }
    }

    return resistances;
  }

  getCondition(): MoveConditionFunc {
    // TODO: Does this count dancer?
    return (user, target) => {
      return !user.isTerastallized && target.getLastXMoves(-1).some(tm => tm.move !== MoveId.NONE);
    };
  }
}

/**
 * Drops the target's immunity to types it is immune to
 * and makes its evasiveness be ignored during accuracy
 * checks. Used by: {@linkcode MoveId.ODOR_SLEUTH | Odor Sleuth}, {@linkcode MoveId.MIRACLE_EYE | Miracle Eye} and {@linkcode MoveId.FORESIGHT | Foresight}
 */
export class ExposedMoveAttr extends AddBattlerTagAttr {
  constructor(tagType: BattlerTagType) {
    super(tagType, false, true);
  }

  /**
   * Applies {@linkcode ExposedTag} to the target.
   * @param user {@linkcode Pokemon} using this move
   * @param target {@linkcode Pokemon} target of this move
   * @param move {@linkcode Move} being used
   * @param args N/A
   * @returns `true` if the function succeeds
   */
  apply(user: Pokemon, target: Pokemon, move: Move, args: any[]): boolean {
    if (!super.apply(user, target, move, args)) {
      return false;
    }

    globalScene.phaseManager.queueMessage(
      i18next.t("moveTriggers:exposedMove", {
        pokemonName: getPokemonNameWithAffix(user),
        targetPokemonName: getPokemonNameWithAffix(target),
      }),
    );

    return true;
  }
}

/**
 * Attribute to apply the effects of the move Rage.
 *
 * If the user is attacked while rage is active, they will gain +1 atk boost.
 * @see {@link https://bulbapedia.bulbagarden.net/wiki/Rage_(move)}
 */
export class RageAttr extends MoveEffectAttr {
  constructor() {
    super(true, { trigger: MoveEffectTrigger.PRE_APPLY });
  }

  public override apply(user: Pokemon, _target: Pokemon, move: Move): boolean {
    globalScene.phaseManager.queueMessage(
      i18next.t("moveTriggers:rageIsBuilding", { pokemonName: getPokemonNameWithAffix(user) }),
    );
    user.addTag(BattlerTagType.RAGE, undefined, move.id, user.id);
    return true;
  }
}

